// Replays recorded actual history only; no hypothetical move search or choice.
const cols="ABCDEFGHJ";
function neighbors(p){const x=cols.indexOf(p[0]),y=Number(p[1]);return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,z])=>a>=0&&a<9&&z>=1&&z<=9).map(([a,z])=>cols[a]+z);}
function group(board,p){const color=board[p],stones=[],liberties=new Set(),seen=new Set([p]),stack=[p];while(stack.length){const q=stack.pop();stones.push(q);for(const n of neighbors(q)){if(board[n]===".")liberties.add(n);else if(board[n]===color&&!seen.has(n)){seen.add(n);stack.push(n);}}}return {stones,liberties:[...liberties]};}
function verify(calls,moves){const board={},captures={B:0,W:0},events=[],checks=[];for(const x of cols)for(let y=1;y<=9;y++)board[x+y]=".";let index=0;for(let i=0;i<moves.length;i++){const {color,move}=moves[i],own=color==="B"?"X":"O",enemy=own==="X"?"O":"X";if(move!=="pass"){if(board[move]!==".")throw Error("Occupied actual move"+(i+1));board[move]=own;const removed=[];for(const n of neighbors(move)){if(board[n]===enemy){const g=group(board,n);if(!g.liberties.length){for(const p of g.stones){board[p]=".";removed.push(p);}}}}if(!group(board,move).liberties.length)throw Error("Suicide actual move"+(i+1));if(removed.length){captures[color]+=removed.length;events.push({number:i+1,color,move,captured:removed.sort()});}}
const expected=calls[index];if(expected&&Object.keys(expected.board).length===81){const nextNumber=expected.text.match(/Move number: (\d+)/);if(nextNumber&&Number(nextNumber[1])===i+2){for(const p of Object.keys(board))if(board[p]!==expected.board[p])throw Error("Board mismatch"+(i+1)+" "+p);const c=expected.text.match(/Captured by Black: (\d+); by White: (\d+)/);if(!c||Number(c[1])!==captures.B||Number(c[2])!==captures.W)throw Error("Capture mismatch"+(i+1));checks.push({afterMove:i+1,boardMatched:true,captures:{...captures}});index++;}}}
if(index!==calls.length)throw Error("Unchecked returned boards");const seen=new Set(),area={B:0,W:0,neutral:0},stones={B:0,W:0},regions=[];for(const p of Object.keys(board)){if(board[p]!=="."){const c=board[p]==="X"?"B":"W";stones[c]++;area[c]++;continue;}if(seen.has(p))continue;const stack=[p],points=[],border=new Set();seen.add(p);while(stack.length){const q=stack.pop();points.push(q);for(const n of neighbors(q)){if(board[n]!==".")border.add(board[n]);else if(!seen.has(n)){seen.add(n);stack.push(n);}}}const owner=border.size===1?([...border][0]==="X"?"B":"W"):null;area[owner||"neutral"]+=points.length;regions.push({points:points.sort(),owner});}return {moves,captureEvents:events,checks,final:{board,captures,stones,regions,area,whiteMargin:area.W+7-area.B}};}
